/**
 * Per-deployment Google API configuration for Doorprints.
 * This file is generated by CI from environment variables at build/deploy time.
 *
 * Default (empty config) disables Google Drive feature.
 * CI must populate: window.__DOORPRINTS__.googleClientId and .googleRedirectUri
 *
 * S4b-BL-117, docs/15 §9.4
 */
window.__DOORPRINTS__ = window.__DOORPRINTS__ || {};
window.__DOORPRINTS__.googleClientId = window.__DOORPRINTS__.googleClientId || '';
window.__DOORPRINTS__.googleRedirectUri = window.__DOORPRINTS__.googleRedirectUri || '';
